CREATE DATABASE IF NOT EXISTS seed_engine CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE seed_engine;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(64) NOT NULL UNIQUE,salt_hex CHAR(32) NOT NULL,password_hash_hex VARCHAR(128) NOT NULL,role ENUM('user','admin') NOT NULL DEFAULT 'user',enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions(token CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,expires_at TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_session_user(user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS modules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,module_key VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL,version VARCHAR(32) NOT NULL DEFAULT '0.1.0') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS game_nodes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,module_id BIGINT UNSIGNED NOT NULL,parent_id BIGINT UNSIGNED NULL,node_kind VARCHAR(32) NOT NULL,node_key VARCHAR(150) NOT NULL,name VARCHAR(200) NOT NULL,metadata JSON NULL,UNIQUE KEY uq_module_node(module_id,node_key),INDEX ix_parent(parent_id),FOREIGN KEY(module_id) REFERENCES modules(id),FOREIGN KEY(parent_id) REFERENCES game_nodes(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stat_definitions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,node_id BIGINT UNSIGNED NOT NULL UNIQUE,base_value DECIMAL(30,10) NOT NULL DEFAULT 0,min_value DECIMAL(30,10) NULL,max_value DECIMAL(30,10) NULL,unit VARCHAR(40) NULL,formula_key VARCHAR(100) NULL,FOREIGN KEY(node_id) REFERENCES game_nodes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS array_definitions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,node_id BIGINT UNSIGNED NOT NULL UNIQUE,element_type VARCHAR(64) NOT NULL,dimensions TINYINT UNSIGNED NOT NULL DEFAULT 1,fixed_length INT UNSIGNED NULL,FOREIGN KEY(node_id) REFERENCES game_nodes(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS seeds(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,module_id BIGINT UNSIGNED NOT NULL,seed_name VARCHAR(150) NOT NULL,seed_value BIGINT UNSIGNED NOT NULL,algorithm VARCHAR(80) NOT NULL,algorithm_version VARCHAR(32) NOT NULL,parameters JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_seed(module_id,seed_name),FOREIGN KEY(module_id) REFERENCES modules(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS programs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,module_id BIGINT UNSIGNED NOT NULL,program_key VARCHAR(150) NOT NULL,language VARCHAR(16) NOT NULL DEFAULT 'cpp23',entry_point VARCHAR(200) NOT NULL,version VARCHAR(32) NOT NULL DEFAULT '0.1.0',UNIQUE KEY uq_program(module_id,program_key),FOREIGN KEY(module_id) REFERENCES modules(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS math_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,program_id BIGINT UNSIGNED NOT NULL,seed_id BIGINT UNSIGNED NULL,input_json JSON NOT NULL,output_json JSON NULL,status ENUM('queued','running','succeeded','failed') NOT NULL DEFAULT 'queued',error_message TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(program_id) REFERENCES programs(id),FOREIGN KEY(seed_id) REFERENCES seeds(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,target_user_id BIGINT UNSIGNED NULL,detail VARCHAR(500) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX ix_audit_created(created_at)) ENGINE=InnoDB;
